/* =========================================================
GLOBAL / FOUNDATION
========================================================= */
:root {
  --hc-bg: #f7f3ee;
  --hc-surface: rgba(252, 250, 247, 0.72);
  --hc-surface-strong: rgba(252, 250, 247, 0.88);
  --hc-text: #2f312d;
  --hc-text-soft: #7e8078;
  --hc-line: #d8d1c7;
  --hc-accent: #8fa08c;
  --hc-accent-dark: #6f7f6d;
  --hc-shadow: 0 24px 60px rgba(32, 28, 23, 0.1);
  --hc-shadow-soft: 0 12px 28px rgba(32, 28, 23, 0.08);
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  margin: 0;
  background: var(--hc-bg);
  color: var(--hc-text);
  font-family: 'Urbanist', sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
a {
  text-decoration: none;
}
.hero-font-serif {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.02em;
}

/* =========================================================
SECTION 1: HERO
========================================================= */
.hero-homecare {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: linear-gradient(180deg, #f7f3ee 0%, #f1eee8 62%, #e8ede6 100%);
}
.hero-shell {
  position: relative;
  z-index: 2;
  max-width: 1440px;
  margin: 0 auto;
  padding: 48px 28px 76px;
  filter: drop-shadow(0 18px 30px rgba(82, 96, 79, 0.08)) drop-shadow(0 4px 12px rgba(82, 96, 79, 0.04));
}
.hero-frame {
  position: relative;
  min-height: 860px;
  overflow: hidden;
  background: #ece6de;
  border: 1px solid var(--hc-line);
  box-shadow: 0 4px 12px rgba(32, 28, 23, 0.03);
  clip-path: polygon(20px 0, 100% 0, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%, 0 20px);
}
.hero-grid-lines {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  padding: 0 28px;
  pointer-events: none;
  opacity: 0.45;
}
.hero-grid-line {
  width: 1px;
  height: 100%;
  background: linear-gradient(180deg, rgba(47, 49, 45, 0.06), rgba(47, 49, 45, 0.10), rgba(47, 49, 45, 0.04));
}
.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1.01);
}
.hero-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(232, 239, 231, 0.92) 0%, rgba(232, 239, 231, 0.56) 28%, rgba(232, 239, 231, 0.15) 62%, rgba(232, 239, 231, 0.02) 100%),
    linear-gradient(180deg, rgba(232, 239, 231, 0.02), rgba(232, 239, 231, 0.10) 70%, rgba(232, 239, 231, 0.16) 100%);
  pointer-events: none;
}
.hero-nav-wrap {
  position: fixed;
  top: 20px;
  left: 0;
  right: 0;
  z-index: 9999;
  display: flex;
  justify-content: center;
  padding: 0 28px;
  pointer-events: none;
}
.hero-nav {
  width: min(100%, 1120px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 10px 12px 10px 18px;
  background: rgba(252, 250, 247, 0.82);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(216, 209, 199, 0.92);
  box-shadow: 0 18px 40px rgba(32, 28, 23, 0.14), 0 6px 18px rgba(32, 28, 23, 0.08);
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
  pointer-events: auto;
}
.hero-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.hero-brand-mark {
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--hc-text);
  color: #fcfaf7;
  border: 1px solid rgba(47, 49, 45, 0.10);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  flex: 0 0 auto;
}
.hero-brand-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hero-brand-name {
  font-size: 16px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--hc-text);
}
.hero-brand-sub {
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--hc-text-soft);
}
.hero-nav-links {
  display: flex;
  align-items: center;
  gap: 34px;
}
.hero-nav-links a {
  font-size: 13px;
  font-weight: 600;
  color: var(--hc-text-soft);
  transition: color 180ms ease, opacity 180ms ease;
}
.hero-nav-links a:hover,
.hero-nav-links a.is-active {
  color: var(--hc-text);
}
.hero-nav-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0 18px;
  background: var(--hc-accent);
  color: #fcfaf7;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: background 180ms ease, transform 180ms ease;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.hero-nav-cta:hover {
  background: var(--hc-accent-dark);
  transform: translateY(-1px);
}
.hero-content {
  position: relative;
  z-index: 3;
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 170px 40px 90px;
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 42px;
  align-items: center;
  min-height: 860px;
}
.hero-copy {
  max-width: 620px;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 34px;
  padding: 0 14px;
  margin-bottom: 28px;
  background: rgba(252, 250, 247, 0.58);
  border: 1px solid rgba(216, 209, 199, 0.90);
  color: var(--hc-text-soft);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.hero-eyebrow-dot {
  width: 7px;
  height: 7px;
  background: var(--hc-accent);
  box-shadow: 0 0 0 6px rgba(143, 160, 140, 0.14);
  border-radius: 999px;
  flex: 0 0 auto;
}
.hero-title {
  margin: 0 0 24px;
  font-size: clamp(3.4rem, 7vw, 6.8rem);
  line-height: 0.90;
  letter-spacing: -0.075em;
  font-weight: 500;
  color: var(--hc-text);
}
.hero-title-accent {
  display: block;
  color: #4f5d4d;
}
.hero-description {
  max-width: 510px;
  margin: 0 0 34px;
  padding-left: 18px;
  border-left: 1px solid rgba(47, 49, 45, 0.16);
  font-size: 17px;
  line-height: 1.85;
  color: rgba(47, 49, 45, 0.78);
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 30px;
}
.hero-btn-primary,
.hero-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 26px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: transform 180ms ease, background 180ms ease, border-color 180ms ease, color 180ms ease;
}
.hero-btn-primary {
  background: var(--hc-text);
  color: #fcfaf7;
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
}
.hero-btn-primary:hover {
  background: #1f201d;
  transform: translateY(-1px);
}
.hero-btn-secondary {
  background: rgba(252, 250, 247, 0.72);
  border: 1px solid rgba(216, 209, 199, 0.95);
  color: var(--hc-text);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
}
.hero-btn-secondary:hover {
  background: rgba(252, 250, 247, 0.62);
  border-color: rgba(143, 160, 140, 0.80);
  transform: translateY(-1px);
}
.hero-trust {
  display: flex;
  align-items: center;
  gap: 14px;
  max-width: 430px;
  padding-top: 20px;
  border-top: 1px solid rgba(143, 160, 140, 0.42);
}
.hero-trust-stack {
  display: flex;
  margin-left: 2px;
}
.hero-trust-dot {
  width: 30px;
  height: 30px;
  margin-left: -8px;
  border: 2px solid #f7f3ee;
  border-radius: 999px;
  background: linear-gradient(180deg, #dcd4ca, #cfc7bc);
}
.hero-trust-dot:first-child {
  margin-left: 0;
  background: linear-gradient(180deg, #ece6dd, #d9d0c4);
}
.hero-trust-dot:nth-child(2) {
  background: linear-gradient(180deg, #b9c4b5, #9dad99);
}
.hero-trust-dot:nth-child(3) {
  background: linear-gradient(180deg, #e2d7cb, #ccbda9);
}
.hero-trust-text {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--hc-text-soft);
}
.hero-visual {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
}
.hero-floating-card {
  position: relative;
  width: min(100%, 390px);
  padding: 26px 24px 24px;
  background: rgba(252, 250, 247, 0.88);
  border: 1px solid rgba(216, 209, 199, 0.92);
  backdrop-filter: blur(18px);
  box-shadow: var(--hc-shadow);
  clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px);
}
.hero-card-kicker {
  display: inline-block;
  margin-bottom: 14px;
  color: var(--hc-accent-dark);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.hero-card-title {
  margin: 0 0 18px;
  color: var(--hc-text);
  font-size: 28px;
  line-height: 1;
  letter-spacing: -0.05em;
  font-weight: 600;
}
.hero-card-list {
  display: grid;
  gap: 14px;
  margin: 0 0 20px;
  padding: 0;
  list-style: none;
}
.hero-card-item {
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 12px;
  align-items: start;
  padding-top: 14px;
  border-top: 1px solid rgba(143, 160, 140, 0.34);
}
.hero-card-item:first-child {
  padding-top: 0;
  border-top: none;
}
.hero-card-icon {
  color: var(--hc-accent);
  margin-top: 1px;
}
.hero-card-item strong {
  display: block;
  margin-bottom: 4px;
  color: var(--hc-text);
  font-size: 14px;
  line-height: 1.3;
  font-weight: 700;
}
.hero-card-item span {
  display: block;
  color: var(--hc-text-soft);
  font-size: 13px;
  line-height: 1.75;
}
.hero-card-footer {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding-top: 18px;
  border-top: 1px solid rgba(143, 160, 140, 0.34);
}
.hero-card-meta {
  color: var(--hc-text-soft);
  font-size: 11px;
  line-height: 1.45;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.hero-card-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--hc-text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  white-space: nowrap;
}
@media (max-width: 1080px) {
  .hero-content {
    grid-template-columns: 1fr;
    gap: 28px;
    padding-top: 170px;
  }
  .hero-copy {
    max-width: 100%;
  }
  .hero-visual {
    min-height: auto;
    justify-content: flex-start;
  }
  .hero-floating-card {
    width: min(100%, 420px);
  }
  .hero-nav-links {
    display: none;
  }
}
@media (max-width: 720px) {
  .hero-shell {
    padding: 14px 14px 28px;
  }
  .hero-frame {
    min-height: 860px;
  }
  .hero-nav-wrap {
    top: 14px;
    left: 14px;
    right: 14px;
    padding: 0;
  }
  .hero-nav {
    padding: 10px 10px 10px 14px;
  }
  .hero-brand-sub {
    display: none;
  }
  .hero-nav-cta {
    min-height: 40px;
    padding: 0 14px;
    font-size: 11px;
  }
  .hero-content {
    min-height: 860px;
    padding: 132px 20px 54px;
  }
  .hero-grid-lines {
    padding: 0 14px;
  }
  .hero-grid-line:nth-child(2),
  .hero-grid-line:nth-child(3) {
    display: none;
  }
  .hero-description {
    padding-left: 14px;
    font-size: 15px;
  }
  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .hero-btn-primary,
  .hero-btn-secondary {
    width: 100%;
  }
  .hero-trust {
    max-width: 100%;
  }
  .hero-floating-card {
    width: 100%;
  }
  .hero-card-footer {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* =========================================================
SECTION 2: SERVICES CATALOG
========================================================= */
.services-catalog {
  position: relative;
  width: 100%;
  background:
    radial-gradient(circle at top left, rgba(143, 160, 140, 0.08), transparent 24%),
    linear-gradient(180deg, #eef2ec 0%, #e8ede6 100%);
  border-top: 1px solid rgba(143, 160, 140, 0.12);
  border-bottom: 1px solid rgba(143, 160, 140, 0.12);
  overflow: hidden;
}
.services-catalog-shell {
  max-width: 1400px;
  margin: 0 auto;
  padding: 116px 28px 124px;
}
.services-catalog-head {
  max-width: 1080px;
  margin: 0 auto 64px;
  text-align: center;
}
.services-catalog-title {
  margin: 0;
  color: var(--hc-text);
  font-size: clamp(3rem, 5vw, 5.2rem);
  line-height: 0.95;
  letter-spacing: -0.06em;
  font-weight: 600;
}
.services-catalog-title-accent {
  color: #4f5d4d;
}
.services-catalog-description {
  max-width: 58ch;
  margin: 28px auto 0;
  color: rgba(47, 49, 45, 0.68);
  font-size: 18px;
  line-height: 1.75;
}
.services-catalog-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  align-items: stretch;
}
.service-catalog-column {
  display: grid;
  grid-template-rows: repeat(2, 1fr);
  gap: 16px;
}
.service-catalog-card {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: 28px;
  background: linear-gradient(180deg, rgba(236, 242, 234, 0.96) 0%, rgba(230, 237, 228, 0.98) 100%);
  border: 1px solid rgba(143, 160, 140, 0.10);
  box-shadow:
    0 10px 22px rgba(32, 28, 23, 0.04),
    0 2px 8px rgba(32, 28, 23, 0.025);
  transition: background 180ms ease, box-shadow 180ms ease, transform 180ms ease, border-color 180ms ease;
}
.service-catalog-column.is-outer .service-catalog-card {
  background: linear-gradient(180deg, rgba(223, 232, 220, 0.98) 0%, rgba(216, 226, 213, 0.99) 100%);
}
.service-catalog-column.is-middle .service-catalog-card {
  background: linear-gradient(180deg, rgba(244, 248, 241, 0.96) 0%, rgba(239, 245, 236, 0.98) 100%);
}
.service-catalog-card:hover {
  transform: translateY(-2px);
  box-shadow:
    0 14px 28px rgba(32, 28, 23, 0.05),
    0 4px 10px rgba(32, 28, 23, 0.03);
}
.service-catalog-media {
  position: relative;
  margin-bottom: 22px;
  overflow: hidden;
  background: #d9ded7;
  aspect-ratio: 16 / 10;
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  box-shadow: 0 10px 24px rgba(32, 28, 23, 0.06);
}
.service-catalog-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition: transform 700ms ease;
}
.service-catalog-card:hover .service-catalog-media img {
  transform: scale(1.04);
}
.service-catalog-body {
  display: flex;
  flex-direction: column;
  flex: 1;
}
.service-catalog-label {
  margin: 0 0 4px;
  color: var(--hc-text);
  font-size: 18px;
  line-height: 1.15;
  letter-spacing: -0.03em;
  font-weight: 700;
}
.service-catalog-meta {
  margin: 0 0 14px;
  color: #6e816b;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.20em;
  text-transform: uppercase;
}
.service-catalog-copy {
  margin: 0;
  color: rgba(47, 49, 45, 0.68);
  font-size: 15px;
  line-height: 1.75;
}
.service-catalog-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding-top: 22px;
  color: var(--hc-text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.service-catalog-link iconify-icon {
  transition: transform 180ms ease;
}
.service-catalog-card:hover .service-catalog-link iconify-icon {
  transform: translateX(2px);
}
.services-catalog-cta-wrap {
  display: flex;
  justify-content: center;
  margin-top: 56px;
}
.services-catalog-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0 18px;
  background: var(--hc-accent);
  color: #fcfaf7;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: background 180ms ease, transform 180ms ease;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.services-catalog-button:hover {
  background: var(--hc-accent-dark);
  transform: translateY(-1px);
}
.service-catalog-reveal {
  opacity: 0;
  animation: heroFadeUp 0.8s ease-out forwards;
  animation-play-state: paused;
}
.service-catalog-reveal.is-visible {
  animation-play-state: running;
}
@media (max-width: 1080px) {
  .services-catalog-shell {
    padding: 102px 24px 112px;
  }
  .services-catalog-head {
    max-width: 860px;
    margin-bottom: 52px;
  }
  .services-catalog-description {
    max-width: 46ch;
  }
  .services-catalog-grid {
    grid-template-columns: 1fr;
  }
  .service-catalog-column {
    grid-template-rows: auto;
  }
}
@media (max-width: 720px) {
  .services-catalog-shell {
    padding: 88px 16px 94px;
  }
  .services-catalog-description {
    max-width: 100%;
    font-size: 16px;
  }
  .service-catalog-card {
    padding: 22px;
  }
  .service-catalog-label {
    font-size: 17px;
  }
  .services-catalog-cta-wrap {
    margin-top: 42px;
  }
}

/* =========================================================
SECTION 3: STANDARD OF CARE
========================================================= */
.standard-care {
  position: relative;
  width: 100%;
  background:
    radial-gradient(circle at top right, rgba(143, 160, 140, 0.05), transparent 22%),
    linear-gradient(180deg, #f8faf6 0%, #f2f5f0 100%);
  border-top: 1px solid rgba(143, 160, 140, 0.08);
  border-bottom: 1px solid rgba(143, 160, 140, 0.08);
}
.standard-care-shell {
  max-width: 1400px;
  margin: 0 auto;
  padding: 116px 28px 124px;
}
.standard-care-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 52px;
}
.standard-care-head-copy {
  max-width: 760px;
}
.standard-care-title {
  margin: 0;
  color: var(--hc-text);
  font-size: clamp(2.6rem, 4.6vw, 4.6rem);
  line-height: 0.95;
  letter-spacing: -0.06em;
  font-weight: 600;
}
.standard-care-description {
  margin: 14px 0 0;
  max-width: 42ch;
  color: rgba(47, 49, 45, 0.68);
  font-size: 18px;
  line-height: 1.75;
}
.standard-care-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--hc-text);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
  transition: color 180ms ease, transform 180ms ease;
}
.standard-care-link iconify-icon {
  transition: transform 180ms ease;
}
.standard-care-link:hover {
  color: var(--hc-accent-dark);
}
.standard-care-link:hover iconify-icon {
  transform: translateX(2px);
}
.standard-care-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 24px;
}
.standard-care-card {
  position: relative;
  min-height: 320px;
  padding: 26px 26px 28px;
  background: linear-gradient(180deg, rgba(238, 243, 236, 0.96) 0%, rgba(231, 238, 229, 0.98) 100%);
  border: 1px solid rgba(143, 160, 140, 0.18);
  box-shadow:
    0 10px 24px rgba(82, 96, 79, 0.05),
    0 2px 8px rgba(82, 96, 79, 0.03);
  transition: transform 220ms ease, background 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
}
.standard-care-card:hover {
  transform: translateY(-2px);
  background: linear-gradient(180deg, rgba(242, 247, 240, 0.98) 0%, rgba(235, 242, 233, 1) 100%);
  border-color: rgba(143, 160, 140, 0.26);
  box-shadow:
    0 14px 30px rgba(82, 96, 79, 0.06),
    0 4px 10px rgba(82, 96, 79, 0.04);
}
.standard-care-card-badge-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 24px;
}
.standard-care-card-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid rgba(111, 127, 109, 0.22);
  background: rgba(143, 160, 140, 0.12);
  color: #5f705d;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: -0.01em;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.standard-care-card-badge iconify-icon {
  color: var(--hc-accent-dark);
}
.standard-care-card-index {
  color: rgba(47, 49, 45, 0.42);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.standard-care-card-title {
  margin: 0 0 10px;
  color: var(--hc-text);
  font-size: 28px;
  line-height: 1.02;
  letter-spacing: -0.045em;
  font-weight: 600;
}
.standard-care-card-text {
  margin: 0;
  color: rgba(47, 49, 45, 0.68);
  font-size: 16px;
  line-height: 1.7;
}
.standard-care-card-list {
  display: grid;
  gap: 12px;
  margin: 24px 0 0;
  padding: 0;
  list-style: none;
}
.standard-care-card-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: rgba(47, 49, 45, 0.74);
  font-size: 15px;
  line-height: 1.6;
}
.standard-care-card-list iconify-icon {
  color: var(--hc-accent);
  margin-top: 2px;
  flex: 0 0 auto;
}
.standard-care-reveal {
  opacity: 0;
  animation: heroFadeUp 0.8s ease-out forwards;
  animation-play-state: paused;
}
.standard-care-reveal.is-visible {
  animation-play-state: running;
}
@media (max-width: 1200px) {
  .standard-care-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 1080px) {
  .standard-care-shell {
    padding: 102px 24px 112px;
  }
  .standard-care-head {
    flex-direction: column;
    align-items: flex-start;
    margin-bottom: 44px;
  }
  .standard-care-description {
    max-width: 48ch;
  }
}
@media (max-width: 720px) {
  .standard-care-shell {
    padding: 88px 16px 94px;
  }
  .standard-care-grid {
    grid-template-columns: 1fr;
    gap: 18px;
  }
  .standard-care-card {
    min-height: auto;
    padding: 22px 22px 24px;
  }
  .standard-care-title {
    font-size: clamp(2.2rem, 10vw, 3.2rem);
  }
  .standard-care-description {
    max-width: 100%;
    font-size: 16px;
  }
  .standard-care-card-title {
    font-size: 24px;
  }
}

/* =========================================================
SECTION 4: PROCESS
========================================================= */
.process-section {
  position: relative;
  width: 100%;
  background: linear-gradient(180deg, #edf1eb 0%, #e7ece5 100%);
  border-top: 1px solid rgba(143, 160, 140, 0.12);
  border-bottom: 1px solid rgba(143, 160, 140, 0.12);
}
.process-shell {
  max-width: 1280px;
  margin: 0 auto;
  padding: 112px 28px 120px;
}
.process-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 42px;
  align-items: center;
}
.process-visual {
  position: relative;
  min-height: 560px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(242, 246, 240, 0.9) 0%, rgba(235, 241, 233, 0.94) 100%);
  border: 1px solid rgba(143, 160, 140, 0.16);
  box-shadow:
    0 16px 34px rgba(82, 96, 79, 0.06),
    0 5px 14px rgba(82, 96, 79, 0.035);
  clip-path: polygon(18px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%, 0 18px);
}
.process-visual::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 1px 1px, rgba(143, 160, 140, 0.16) 1px, transparent 0);
  background-size: 18px 18px;
  opacity: 0.46;
  pointer-events: none;
}
.process-stage {
  position: relative;
  width: min(100%, 520px);
  height: 320px;
  margin: 118px auto 0;
}
.process-plane-back,
.process-plane-mid,
.process-plane-front {
  position: absolute;
  inset: 0;
}
.process-plane-back {
  inset: 32px;
  transform: rotate(-10deg);
  border: 1px dashed rgba(111, 127, 109, 0.22);
  background: rgba(245, 248, 243, 0.26);
}
.process-plane-mid {
  inset: 16px;
  transform: rotate(-6deg);
  border: 1px dashed rgba(111, 127, 109, 0.24);
  background: rgba(238, 243, 236, 0.34);
}
.process-plane-front {
  overflow: hidden;
  transform: rotate(-3deg);
  border: 1px solid rgba(143, 160, 140, 0.18);
  background: #dfe6dc;
  box-shadow: 0 20px 36px rgba(32, 28, 23, 0.08);
}
.process-plane-front img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: saturate(0.9) contrast(0.97) brightness(1.01);
}
.process-chip-row {
  position: absolute;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 10px;
}
.process-chip-row.top-left {
  top: 22px;
  left: -8px;
}
.process-chip-row.mid-right {
  top: 116px;
  right: -10px;
}
.process-chip-row.bottom-left {
  bottom: 54px;
  left: -2px;
}
.process-step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 32px;
  background: var(--hc-text);
  color: #fcfaf7;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.process-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 14px;
  background: rgba(252, 250, 247, 0.92);
  color: var(--hc-text);
  border: 1px solid rgba(143, 160, 140, 0.18);
  font-size: 12px;
  font-weight: 700;
  box-shadow: 0 8px 18px rgba(32, 28, 23, 0.05);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.process-chip iconify-icon {
  color: var(--hc-accent-dark);
}
.process-copy {
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.process-kicker {
  margin: 0;
  color: var(--hc-text-soft);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.process-title {
  margin: 0;
  color: var(--hc-text);
  font-size: clamp(2.8rem, 5vw, 4.4rem);
  line-height: 0.95;
  letter-spacing: -0.06em;
  font-weight: 600;
}
.process-description {
  max-width: 34ch;
  margin: 0;
  color: rgba(47, 49, 45, 0.7);
  font-size: 18px;
  line-height: 1.75;
}
.process-steps {
  display: grid;
  gap: 20px;
  margin-top: 4px;
}
.process-step {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 14px;
  align-items: start;
}
.process-step-index {
  padding-top: 2px;
  color: var(--hc-text);
  font-size: 21px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.04em;
}
.process-step-title {
  margin: 0 0 6px;
  color: var(--hc-text);
  font-size: 22px;
  line-height: 1.08;
  letter-spacing: -0.04em;
  font-weight: 600;
}
.process-step-text {
  max-width: 40ch;
  margin: 0;
  color: rgba(47, 49, 45, 0.68);
  font-size: 16px;
  line-height: 1.7;
}
.process-cta-wrap {
  margin-top: 8px;
}
.process-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  padding: 0 18px;
  background: var(--hc-accent);
  color: #fcfaf7;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: background 180ms ease, transform 180ms ease;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.process-cta:hover {
  background: var(--hc-accent-dark);
  transform: translateY(-1px);
}
.process-reveal {
  opacity: 0;
  animation: heroFadeUp 0.8s ease-out forwards;
  animation-play-state: paused;
}
.process-reveal.is-visible {
  animation-play-state: running;
}
@media (max-width: 1080px) {
  .process-shell {
    padding: 100px 24px 108px;
  }
  .process-grid {
    grid-template-columns: 1fr;
    gap: 34px;
  }
  .process-copy {
    order: 2;
  }
  .process-visual {
    order: 1;
    min-height: 500px;
  }
  .process-stage {
    margin-top: 92px;
  }
}
@media (max-width: 720px) {
  .process-shell {
    padding: 88px 16px 94px;
  }
  .process-visual {
    min-height: 420px;
  }
  .process-stage {
    width: 100%;
    max-width: 340px;
    height: 240px;
    margin-top: 96px;
  }
  .process-step {
    grid-template-columns: 44px 1fr;
    gap: 12px;
  }
  .process-step-title {
    font-size: 19px;
  }
  .process-step-text,
  .process-description {
    font-size: 15px;
  }
  .process-chip-row.top-left {
    top: 6px;
    left: -2px;
  }
  .process-chip-row.mid-right {
    top: 82px;
    right: -2px;
  }
  .process-chip-row.bottom-left {
    bottom: 38px;
    left: 0;
  }
  .process-chip {
    min-height: 30px;
    padding: 0 12px;
    font-size: 11px;
  }
  .process-step-number {
    width: 38px;
    height: 30px;
    font-size: 10px;
  }
}

