/* =========================================================
SECTION 4: PROCESS
========================================================= */
.process-section {
  position: relative;
  width: 100%;
  background: linear-gradient(180deg, #edf1eb 0%, #e7ece5 100%);
  border-top: 1px solid rgba(143, 160, 140, 0.12);
  border-bottom: 1px solid rgba(143, 160, 140, 0.12);
}
.process-shell {
  max-width: 1280px;
  margin: 0 auto;
  padding: 112px 28px 120px;
}
.process-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 42px;
  align-items: center;
}
.process-visual {
  position: relative;
  min-height: 560px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(242, 246, 240, 0.9) 0%, rgba(235, 241, 233, 0.94) 100%);
  border: 1px solid rgba(143, 160, 140, 0.16);
  box-shadow:
    0 16px 34px rgba(82, 96, 79, 0.06),
    0 5px 14px rgba(82, 96, 79, 0.035);
  clip-path: polygon(18px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%, 0 18px);
}
.process-visual::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 1px 1px, rgba(143, 160, 140, 0.16) 1px, transparent 0);
  background-size: 18px 18px;
  opacity: 0.46;
  pointer-events: none;
}
.process-stage {
  position: relative;
  width: min(100%, 520px);
  height: 320px;
  margin: 118px auto 0;
}
.process-plane-back,
.process-plane-mid,
.process-plane-front {
  position: absolute;
  inset: 0;
}
.process-plane-back {
  inset: 32px;
  transform: rotate(-10deg);
  border: 1px dashed rgba(111, 127, 109, 0.22);
  background: rgba(245, 248, 243, 0.26);
}
.process-plane-mid {
  inset: 16px;
  transform: rotate(-6deg);
  border: 1px dashed rgba(111, 127, 109, 0.24);
  background: rgba(238, 243, 236, 0.34);
}
.process-plane-front {
  overflow: hidden;
  transform: rotate(-3deg);
  border: 1px solid rgba(143, 160, 140, 0.18);
  background: #dfe6dc;
  box-shadow: 0 20px 36px rgba(32, 28, 23, 0.08);
}
.process-plane-front img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: saturate(0.9) contrast(0.97) brightness(1.01);
}
.process-chip-row {
  position: absolute;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 10px;
}
.process-chip-row.top-left {
  top: 22px;
  left: -8px;
}
.process-chip-row.mid-right {
  top: 116px;
  right: -10px;
}
.process-chip-row.bottom-left {
  bottom: 54px;
  left: -2px;
}
.process-step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 32px;
  background: var(--hc-text);
  color: #fcfaf7;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.process-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 14px;
  background: rgba(252, 250, 247, 0.92);
  color: var(--hc-text);
  border: 1px solid rgba(143, 160, 140, 0.18);
  font-size: 12px;
  font-weight: 700;
  box-shadow: 0 8px 18px rgba(32, 28, 23, 0.05);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.process-chip iconify-icon {
  color: var(--hc-accent-dark);
}
.process-copy {
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.process-kicker {
  margin: 0;
  color: var(--hc-text-soft);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.process-title {
  margin: 0;
  color: var(--hc-text);
  font-size: clamp(2.8rem, 5vw, 4.4rem);
  line-height: 0.95;
  letter-spacing: -0.06em;
  font-weight: 600;
}
.process-description {
  max-width: 34ch;
  margin: 0;
  color: rgba(47, 49, 45, 0.7);
  font-size: 18px;
  line-height: 1.75;
}
.process-steps {
  display: grid;
  gap: 20px;
  margin-top: 4px;
}
.process-step {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 14px;
  align-items: start;
}
.process-step-index {
  padding-top: 2px;
  color: var(--hc-text);
  font-size: 21px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.04em;
}
.process-step-title {
  margin: 0 0 6px;
  color: var(--hc-text);
  font-size: 22px;
  line-height: 1.08;
  letter-spacing: -0.04em;
  font-weight: 600;
}
.process-step-text {
  max-width: 40ch;
  margin: 0;
  color: rgba(47, 49, 45, 0.68);
  font-size: 16px;
  line-height: 1.7;
}
.process-cta-wrap {
  margin-top: 8px;
}
.process-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  padding: 0 18px;
  background: var(--hc-accent);
  color: #fcfaf7;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: background 180ms ease, transform 180ms ease;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
}
.process-cta:hover {
  background: var(--hc-accent-dark);
  transform: translateY(-1px);
}
.process-reveal {
  opacity: 0;
  animation: heroFadeUp 0.8s ease-out forwards;
  animation-play-state: paused;
}
.process-reveal.is-visible {
  animation-play-state: running;
}
@media (max-width: 1080px) {
  .process-shell {
    padding: 100px 24px 108px;
  }
  .process-grid {
    grid-template-columns: 1fr;
    gap: 34px;
  }
  .process-copy {
    order: 2;
  }
  .process-visual {
    order: 1;
    min-height: 500px;
