  max-width: 44ch;
  color: rgba(47, 49, 45, 0.68);
  font-size: 16px;
  line-height: 1.75;
}
.final-conversion-faq-list {
  max-width: 920px;
  margin: 0 auto;
}
.final-conversion-faq-item {
  border-bottom: 1px solid rgba(216, 209, 199, 0.72);
}
.final-conversion-faq-item:last-child {
  border-bottom: none;
}
.final-conversion-faq-item summary {
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 0;
  color: var(--hc-text);
  font-size: 16px;
  line-height: 1.5;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.final-conversion-faq-item summary::-webkit-details-marker {
  display: none;
}
.final-conversion-faq-icon {
  color: var(--hc-text-soft);
  transition: transform 180ms ease, color 180ms ease;
  flex: 0 0 auto;
}
.final-conversion-faq-item[open] .final-conversion-faq-icon {
  transform: rotate(180deg);
  color: var(--hc-accent-dark);
}
.final-conversion-faq-answer {
  padding: 0 42px 22px 0;
  color: rgba(47, 49, 45, 0.68);
  font-size: 15px;
  line-height: 1.8;
}
.final-conversion-reveal {
  opacity: 0;
  animation: heroFadeUp 0.8s ease-out forwards;
  animation-play-state: paused;
}
.final-conversion-reveal.is-visible {
  animation-play-state: running;
}
@media (max-width: 1080px) {
  .final-conversion-shell {
    padding: 102px 24px 112px;
  }
  .final-conversion-quote {
    grid-template-columns: 1fr;
  }
  .final-conversion-context {
    border-right: none;
    border-bottom: 1px solid rgba(216, 209, 199, 0.82);
  }
  .final-conversion-form-grid {
    grid-template-columns: 1fr;
  }
  .final-conversion-checkbox-wrap {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 720px) {
  .final-conversion-shell {
    padding: 88px 16px 94px;
  }
  .final-conversion-context,
  .final-conversion-form-wrap,
  .final-conversion-faq {
    padding-left: 22px;
    padding-right: 22px;
  }
  .final-conversion-title {
    max-width: 100%;
    font-size: clamp(2.3rem, 10vw, 3.4rem);
  }
  .final-conversion-description,
  .final-conversion-faq-description {
    max-width: 100%;
    font-size: 15px;
  }
  .final-conversion-checkbox-wrap {
    grid-template-columns: 1fr;
  }
  .final-conversion-faq-answer {
    padding-right: 0;
  }
}

/* =========================================================
SECTION 8: FOOTER
========================================================= */
.site-footer {
  position: relative;
  width: 100%;
  background: linear-gradient(180deg, #f3eee7 0%, #efe8df 100%);
}
.site-footer-shell {
  max-width: 1400px;
  margin: 0 auto;
  padding: 110px 28px 38px;
}
.site-footer-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.7fr 0.9fr 0.95fr;
  gap: 56px;
}
.site-footer-brand {
  max-width: 280px;
}
.site-footer-brand-mark {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 26px;
}
.site-footer-brand-square {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--hc-text);
  color: #fcfaf7;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.site-footer-brand-name-wrap {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.site-footer-brand-name {
  color: var(--hc-text);
  font-size: 24px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.05em;
}
.site-footer-brand-sub {
  color: var(--hc-text-soft);
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.site-footer-brand-text {
  color: rgba(47, 49, 45, 0.68);
  font-size: 16px;
  line-height: 1.8;
}
.site-footer-col-title {
  display: block;
  margin-bottom: 24px;
  color: rgba(126, 128, 120, 0.7);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.site-footer-links,
.site-footer-contact {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.site-footer-links a,
.site-footer-contact a,
.site-footer-contact p,
.site-footer-note {
  color: var(--hc-text);
  font-size: 16px;
  line-height: 1.7;
  font-weight: 500;
  transition: color 180ms ease;
}
.site-footer-links a:hover,
.site-footer-contact a:hover {
  color: var(--hc-accent-dark);
}
.site-footer-contact p.is-soft,
.site-footer-note,
.site-footer-hours {
  color: rgba(47, 49, 45, 0.66);
  font-weight: 400;
}
.site-footer-hours-wrap {
  margin-top: 26px;
}
.site-footer-hours {
  font-size: 16px;
  line-height: 1.75;
}
.site-footer-service-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 18px;
  color: var(--hc-text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: color 180ms ease, transform 180ms ease;
}
.site-footer-service-link:hover {
  color: var(--hc-accent-dark);
  transform: translateY(-1px);
}
.site-footer-bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-top: 78px;
  padding-top: 24px;
  border-top: 1px solid rgba(216, 209, 199, 0.82);
}
.site-footer-bottom-left {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.site-footer-bottom-line {
  color: rgba(126, 128, 120, 0.62);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.site-footer-bottom-right {
  display: flex;
  align-items: center;
  gap: 28px;
}
.site-footer-meta-links {
  display: flex;
  align-items: center;
  gap: 24px;
}
.site-footer-meta-links a,
.site-footer-social a {
  color: rgba(126, 128, 120, 0.72);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: color 180ms ease;
}
.site-footer-meta-links a:hover,
.site-footer-social a:hover {
  color: var(--hc-text);
}
.site-footer-social {
  display: flex;
  align-items: center;
  gap: 14px;
}
.site-footer-social a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(216, 209, 199, 0.92);
  background: rgba(252, 250, 247, 0.54);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
@media (max-width: 1080px) {
  .site-footer-shell {
    padding: 94px 24px 34px;
  }
  .site-footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 42px 28px;
  }
  .site-footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}
@media (max-width: 720px) {
  .site-footer-shell {
    padding: 78px 16px 28px;
  }
  .site-footer-grid {
    grid-template-columns: 1fr;
    gap: 34px;
  }
  .site-footer-bottom-right {
    flex-direction: column;
    align-items: flex-start;
    gap: 18px;
  }
  .site-footer-meta-links {
    gap: 18px;
  }
  .site-footer-brand-text,
  .site-footer-links a,
  .site-footer-contact a,
  .site-footer-contact p,
  .site-footer-note,
  .site-footer-hours {
    font-size: 15px;
  }
}

/* =========================================================
SHARED ANIMATION / REVEAL SYSTEM
========================================================= */
@keyframes heroFadeUp {
  0% {
    opacity: 0;
    transform: translateY(28px);
    filter: blur(6px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}
@keyframes heroFloatSoft {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-12px);
  }
}
.hero-fade-up {
  opacity: 0;
  animation: heroFadeUp 0.85s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.hero-float-soft {
  animation: heroFloatSoft 7s ease-in-out infinite;
